3	import java.util.Locale;
4	
5	import net.officefloor.plugin.variable.Val;
6	import org.springframework.samples.petclinic.model.Owner;
7	import org.springframework.samples.petclinic.repository.OwnerRepository;
8	
9	/**
10	 * Records on a newly built owner how many existing owners already share its first and
11	 * last name, compared case-insensitively. Runs after {@link BuildOwner} and before
12	 * {@link SaveOwner} — so the new owner itself is not yet persisted and thus not counted —
13	 * and mutates the built owner in place, so the count is stored and returned with it.
14	 */
15	public class AssignNamesakeCount {
16	
17	    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
18	        String key = nameKey(owner.getFirstName(), owner.getLastName());
19	        int count = 0;
20	        for (Owner existing : ownerRepository.findAll()) {
21	            if (key.equals(nameKey(existing.getFirstName(), existing.getLastName()))) {
22	                count++;
23	            }
24	        }
25	        owner.setNamesakeCount(count);
26	    }
27	
28	    /** The first and last name folded to a single case-insensitive key. */
29	    private static String nameKey(String firstName, String lastName) {
30	        return fold(firstName) + '\n' + fold(lastName);
31	    }
32	
33	    private static String fold(String value) {
34	        return value == null ? "" : value.toLowerCase(Locale.ROOT);
35	    }
36	}
