3	/**
4	 * Thrown when a create-owner request has the same derived identity key (normalized
5	 * telephone, email and household id) as an existing owner, i.e. a whole-key match.
6	 * Handled by {@link DuplicateIdentityExceptionHandler}, which responds 409.
7	 */
8	public class DuplicateIdentityException extends Exception {
9	
10	    private final String identityKey;
11	
