package org.springframework.samples.petclinic.rest.function.owner;

import java.util.Locale;
import java.util.regex.Pattern;

/**
 * Shared address normalization for the owner pipelines: trim, collapse internal
 * whitespace, upper-case, and expand common street-type abbreviations
 * ({@code ST->STREET}, {@code RD->ROAD}, {@code AVE->AVENUE}, matched whole-word).
 *
 * <p>Used by {@link ValidateOwnerFields} so a created owner is stored and returned
 * with the canonical address (and the required-field check rejects an address that is
 * blank once normalized), and by {@link Households} so duplicate detection and the
 * shared household id compare addresses in that same canonical form. The transform is
 * idempotent, so re-normalizing an already-normalized address is a no-op.
 */
final class AddressNormalizer {

    private static final Pattern WHITESPACE = Pattern.compile("\\s+");

    private AddressNormalizer() {
    }

    /**
     * @return the canonical form of {@code address}, or {@code ""} when it is null or
     *         blank (so callers can treat a blank-after-normalization address uniformly).
     */
    static String normalize(String address) {
        if (address == null) {
            return "";
        }
        String collapsed = WHITESPACE.matcher(address.strip()).replaceAll(" ").toUpperCase(Locale.ROOT);
        if (collapsed.isEmpty()) {
            return "";
        }
        String[] tokens = collapsed.split(" ");
        StringBuilder normalized = new StringBuilder(collapsed.length());
        for (String token : tokens) {
            if (normalized.length() > 0) {
                normalized.append(' ');
            }
            normalized.append(expand(token));
        }
        return normalized.toString();
    }

    /** Expand a single street-type abbreviation to its full word, else leave it unchanged. */
    private static String expand(String token) {
        switch (token) {
            case "ST":
                return "STREET";
            case "RD":
                return "ROAD";
            case "AVE":
                return "AVENUE";
            default:
                return token;
        }
    }
}

package org.springframework.samples.petclinic.util;

import org.springframework.samples.petclinic.model.Owner;

/**
 * The single derived identity of an owner used for duplicate detection: the normalized
 * telephone, the (optional) email and the household id joined by {@code '|'}. Two owners
 * are duplicates exactly when their whole identity keys are equal, so the previously
 * separate telephone, email and household checks are all expressed through this one value.
 *
 * <p>Both the create pipeline (which compares a candidate's key against every existing
 * owner) and the response mapper (which returns the key) derive it here, so they agree on
 * what an owner's identity is. The telephone and email are already canonical by the time a
 * key is built — the create steps normalize them before the check, and stored owners hold
 * the normalized values — so this class only joins them.
 */
public final class IdentityKey {

    private IdentityKey() {
    }

    /** The identity key for the given owner, from its stored telephone, email and household id. */
    public static String of(Owner owner) {
        return of(owner.getTelephone(), owner.getEmail(), owner.getHouseholdId());
    }

    /**
     * The identity key for the given parts: {@code telephone + '|' + (email or empty) + '|'
     * + (householdId or empty)}. A null or blank email or household id contributes an empty
     * segment, so an owner without one still has a well-formed key.
     */
    public static String of(String telephone, String email, String householdId) {
        return orEmpty(telephone) + '|' + orEmpty(email) + '|' + orEmpty(householdId);
    }

    private static String orEmpty(String value) {
        return (value == null || value.isBlank()) ? "" : value;
    }
}

package org.springframework.samples.petclinic.rest.function.owner;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.repository.OwnerRepository;

/**
 * Records on a newly built owner how many members its household has after this create —
 * the existing owners sharing its {@code householdId} plus the new owner itself. Runs
 * after {@link AssignHousehold} (so the shared id is set and back-filled) and before
 * {@link SaveOwner} (so the new owner is not yet persisted and thus counted only via the
 * {@code +1}), mutating the built owner in place so the size is stored and returned with
 * it. An owner with no shared household ({@code householdId} unset) has a size of one.
 */
public class AssignHouseholdSize {

    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
        owner.setHouseholdSize(Households.memberCount(ownerRepository, owner.getHouseholdId()) + 1);
    }
}

